 });
+
+function streamAll(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const c of chunks) rows.push(...s.push(c));
+  rows.push(...s.end());
+  return rows;
+}
+
+test("any chunking gives the same rows as parseCsv", () => {
+  const inputs = ['a,b\r\n"x,""y""",z\n', "\uFEFFa\r,b\n\n\"q\r\n\"\"\",\"\"\n,", "a\r", '"a"\r\nb,\r', "x,\n"];
+  for (const text of inputs) {
+    for (let cut = 0; cut <= text.length; cut++) {
+      expect(streamAll([text.slice(0, cut), text.slice(cut)])).toEqual(parseCsv(text));
+    }
+    expect(streamAll([...text])).toEqual(parseCsv(text));
+  }
+});
+
+test("a \\r at the end of a chunk waits for the next chunk", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+  expect(streamAll(["a\r", "b\n"])).toEqual([["a\rb"]]);
+});
+
+test("a BOM is dropped only at the very start, even across chunks", () => {
+  expect(streamAll(["\uFEFF", "a"])).toEqual([["a"]]);
+  expect(streamAll(["a", "\uFEFFb"])).toEqual([["a\uFEFFb"]]);
+  expect(streamAll(["\uFEFF"])).toEqual([]);
+});
+
+test("rejects what parseCsv rejects, whatever the chunks", () => {
+  for (const text of ['"a"b', 'a"b', '"open', '"a"\r', '"a"\rb\n', 'x,"a""']) {
+    expect(() => parseCsv(text)).toThrow(SyntaxError);
+    for (let cut = 0; cut <= text.length; cut++) {
+      expect(() => streamAll([text.slice(0, cut), text.slice(cut)])).toThrow(SyntaxError);
+    }
+  }
+});
+
+test("an error right after a chunk boundary is still thrown", () => {
+  expect(() => streamAll(['"a"\r', "b"])).toThrow(SyntaxError);
+  expect(() => streamAll(['"a"', "b"])).toThrow(SyntaxError);
+});
+
+test("a surrogate pair cut across chunks is one character", () => {
+  expect(streamAll(["\uD83D", "\uDE00,x"])).toEqual(parseCsv("\uD83D\uDE00,x"));
+});
+
+test("errors name the offset, as parseCsv does", () => {
+  expect(() => parseCsv('a,"b"c')).toThrow('unexpected "c" after a closing quote at offset 5');
+  expect(() => streamAll(['a,"b"', "c"])).toThrow(new SyntaxError('unexpected "c" after a closing quote at offset 5'));
+  expect(() => streamAll(["ab", '"'])).toThrow(new SyntaxError("a quote in a field that is not quoted, at offset 2"));
+  expect(() => new CsvStream().push('"a"\rb')).toThrow(new SyntaxError("a \\r after a closing quote must be followed by \\n at offset 3"));
+});
+
+test("an input that ends right after a row end has no extra row", () => {
+  expect(streamAll(["a\n"])).toEqual([["a"]]);
+  expect(streamAll([])).toEqual([]);
+  expect(streamAll(["a,", ""])).toEqual([["a", ""]]);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-28 12:41:16.273895913 +0000
+++ b/csv.ts	2026-10-28 12:43:31.549733887 +0000
@@ -50,3 +50,121 @@
   rows.push(row);
   return rows;
 }
+
+type Mode = "fieldStart" | "unquoted" | "crUnquoted" | "quoted" | "quoteSeen" | "crQuoted";
+
+/**
+ * The same format as `parseCsv`, fed a chunk at a time. Work per chunk is proportional to the chunk's length, not
+ * to the input before it. A `\r` at the end of a chunk waits for the next chunk to tell a row end from field text.
+ */
+export class CsvStream {
+  private mode: Mode = "fieldStart";
+  private started = false;
+  private field = "";
+  private row: string[] = [];
+  private rows: string[][] = [];
+  private offset = 0;
+
+  push(chunk: string): string[][] {
+    for (const c of chunk) {
+      if (!this.started) {
+        this.started = true;
+        if (c === "﻿") {
+          this.offset += c.length;
+          continue;
+        }
+      }
+      this.step(c);
+      this.offset += c.length;
+    }
+    return this.take();
+  }
+
+  end(): string[][] {
+    switch (this.mode) {
+      case "quoted":
+        throw new SyntaxError("a quoted field is still open at the end of the input");
+      case "crQuoted":
+        throw new SyntaxError(`a \\r after a closing quote must be followed by \\n at offset ${this.offset - 1}`);
+      case "crUnquoted":
+        this.field += "\r";
+      // falls through
+      case "unquoted":
+      case "quoteSeen":
+        this.endRow();
+        break;
+      case "fieldStart":
+        if (this.row.length > 0) this.endRow();
+        break;
+    }
+    this.mode = "fieldStart";
+    return this.take();
+  }
+
+  private step(c: string) {
+    switch (this.mode) {
+      case "fieldStart":
+        if (c === '"') this.mode = "quoted";
+        else if (c === ",") this.endField();
+        else if (c === "\n") this.endRow();
+        else if (c === "\r") this.mode = "crUnquoted";
+        else {
+          this.field += c;
+          this.mode = "unquoted";
+        }
+        return;
+      case "unquoted":
+        if (c === ",") this.endField();
+        else if (c === "\n") this.endRow();
+        else if (c === "\r") this.mode = "crUnquoted";
+        else if (c === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${this.offset}`);
+        else this.field += c;
+        return;
+      case "crUnquoted":
+        if (c === "\n") {
+          this.endRow();
+          return;
+        }
+        this.field += "\r";
+        this.mode = "unquoted";
+        this.step(c);
+        return;
+      case "quoted":
+        if (c === '"') this.mode = "quoteSeen";
+        else this.field += c;
+        return;
+      case "quoteSeen":
+        if (c === '"') {
+          this.field += '"';
+          this.mode = "quoted";
+        } else if (c === ",") this.endField();
+        else if (c === "\n") this.endRow();
+        else if (c === "\r") this.mode = "crQuoted";
+        else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${this.offset}`);
+        return;
+      case "crQuoted":
+        if (c !== "\n") throw new SyntaxError(`a \\r after a closing quote must be followed by \\n at offset ${this.offset - 1}`);
+        this.endRow();
+        return;
+    }
+  }
+
+  private endField() {
+    this.row.push(this.field);
+    this.field = "";
+    this.mode = "fieldStart";
+  }
+
+  private endRow() {
+    this.endField();
+    this.rows.push(this.row);
+    this.row = [];
+    this.mode = "fieldStart";
+  }
+
+  private take(): string[][] {
+    const rows = this.rows;
+    this.rows = [];
+    return rows;
+  }
+}

