+}
+
+const gitValueOpts = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace']);
+const shortGroup = (w: string, letters: string) => w.startsWith('-') && !w.startsWith('--') && [...letters].some((c) => w.includes(c, 1));
+// True when word `w` is `opt` or an unambiguous-enough prefix of it (at least `--` plus one letter), with an optional =value.
+const longIs = (w: string, opt: string) => w.startsWith('--') && w.split('=')[0].length >= 3 && opt.startsWith(w.split('=')[0]);
+
+function gitHit(args: string[]): Hit | undefined {
+  let i = 0;
+  while (i < args.length && args[i].startsWith('-')) i += gitValueOpts.has(args[i]) ? 2 : 1;
+  const sub = args[i];
+  const rest = args.slice(i + 1);
+  if (sub === 'push') {
+    const force = rest.some(
+      (w) =>
+        ['--force', '--force-with-lease', '--mirror', '--delete', '--prune'].some((o) => longIs(w, o)) ||
+        shortGroup(w, 'fd') ||
+        (!w.startsWith('-') && (w.startsWith('+') || w.startsWith(':'))),
+    );
+    return force ? { name: 'force-push', reason: 'git push would overwrite or delete remote refs' } : undefined;
+  }
+  if (sub === 'reset' && rest.some((w) => longIs(w, '--hard'))) return { name: 'reset-hard', reason: 'git reset --hard discards local changes' };
+  if (sub === 'clean') {
+    if (rest.includes('-n') || rest.some((w) => longIs(w, '--dry-run'))) return undefined;
+    const force = rest.some((w) => longIs(w, '--force') || shortGroup(w, 'f'));
+    return force ? { name: 'clean-force', reason: 'git clean -f deletes untracked files' } : undefined;
+  }
+  return undefined;
+}
+
+// A path the guard cannot resolve before the command runs: a variable, or ~user.
+const unresolvable = (p: string) => p.includes('$') || (p.startsWith('~') && p !== '~' && !p.startsWith('~/'));
+
+function rmHit(args: string[], cwd: string): Hit | undefined {
+  let recursive = false;
+  const targets: string[] = [];
+  let i = 0;
+  for (; i < args.length && args[i] !== '--'; i++) {
+    const w = args[i];
+    if (longIs(w, '--recursive') || shortGroup(w, 'rR')) recursive = true;
+    else if (!w.startsWith('-')) targets.push(w);
+  }
+  targets.push(...args.slice(i + 1));
+  if (!recursive) return undefined;
+  const outside = { name: 'rm-outside' as const, reason: 'recursive rm reaches outside the working directory' };
+  if (targets.length === 0) return outside;
+  for (const t of targets) {
+    if (unresolvable(t) || !insideWorkspace(t, cwd) || sameDir(t, cwd)) return outside;
+  }
+  return undefined;
+}
+
+function findHit(args: string[], cwd: string): Hit | undefined {
+  if (!args.some((w) => w === '-delete' || w === '-exec' || w === '-execdir')) return undefined;
+  // Global options come before the start paths: -H, -L, -P, -O<n>, and -D <opts>.
+  let i = 0;
+  while (i < args.length && /^-[HLP]$|^-O\d*$|^-D$/.test(args[i])) i += args[i] === '-D' ? 2 : 1;
+  const rest = args.slice(i);
+  const firstOpt = rest.findIndex((w) => w.startsWith('-'));
+  const starts = firstOpt === -1 ? rest : rest.slice(0, firstOpt);
+  const paths = starts.length === 0 ? ['.'] : starts;
+  for (const p of paths) {
+    if (unresolvable(p) || !insideWorkspace(p, cwd)) return { name: 'rm-outside', reason: 'find would delete or run commands outside the working directory' };
+  }
+  return undefined;
 }

