@@ -0,0 +1,35 @@
+import { describe, expect, test } from 'bun:test';
+import { applyEdit } from './edit.ts';
+
+const SRC = 'function f() {\n    if (a) {\n        return 1;  \n    }\n}\n';
+
+describe('review', () => {
+  test('not-found hint matches a fragment of a line', () => {
+    const r = applyEdit(SRC, { old_text: 'if (a)\n  zzz', new_text: 'x' });
+    expect('error' in r && r.error).toContain('first line appears at line 2');
+  });
+  test('all-blank old_text gets no hint', () => {
+    const r = applyEdit('a\n\nb\n', { old_text: '\n\n\n', new_text: 'x' });
+    expect('error' in r && r.error).toContain('not found');
+    expect('error' in r && r.error).not.toContain('appears');
+  });
+  test('hint lists at most 5 lines', () => {
+    const r = applyEdit('x\n'.repeat(7), { old_text: 'x\nq', new_text: 'y' });
+    expect('error' in r && r.error).toContain('first line appears at line 1, 2, 3, 4, 5');
+    expect('error' in r && r.error).not.toContain('6');
+  });
+  test('indentation fallback when new_text line is less indented than old_text', () => {
+    const r = applyEdit(SRC, { old_text: '  if (a) {\n    return 1;', new_text: ' if (b) {\n    return 1;' });
+    expect('error' in r).toBe(false);
+    if ('error' in r) return;
+    expect(r.applied.tier).toBe('indentation');
+    expect(r.content).toBe('function f() {\n    if (b) {\n      return 1;\n    }\n}\n');
+  });
+  test('replace_all with multi-line old_text reports the last match end line', () => {
+    const r = applyEdit('a\nb\na\nb\nc\n', { old_text: 'a\nb', new_text: 'x', replace_all: true });
+    expect('error' in r).toBe(false);
+    if ('error' in r) return;
+    expect(r.applied).toEqual({ from: 1, to: 4, tier: 'exact', count: 2 });
+    expect(r.content).toBe('x\nx\nc\n');
+  });
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/edit.ts b/edit.ts
--- a/edit.ts	2026-10-28 12:41:42.427074278 +0000
+++ b/edit.ts	2026-10-28 12:43:29.949733792 +0000
@@ -23,5 +23,69 @@
 // - nothing matched: message contains "not found", and when the first non-blank line of old_text (trimmed) occurs
 //   in some lines of content, "first line appears at line L1, L2" (at most 5 lines).
 export function applyEdit(content: string, edit: TextEdit): { content: string; applied: Applied } | { error: string } {
-  throw new Error('not implemented');
+  const { old_text, new_text, replace_all } = edit;
+  if (old_text === '') return { error: 'old_text is empty; use write to create or overwrite a file' };
+  if (old_text === new_text) return { error: 'old_text and new_text are the same' };
+
+  const exact: number[] = [];
+  for (let i = content.indexOf(old_text); i !== -1; i = content.indexOf(old_text, i + old_text.length)) exact.push(i);
+  if (exact.length > 1 && !replace_all) {
+    return { error: `old_text matches ${exact.length} places (first at line ${lineAt(content, exact[0])}); add context to make it unique or use replace_all` };
+  }
+  if (exact.length > 0) {
+    return {
+      content: content.split(old_text).join(new_text),
+      applied: {
+        from: lineAt(content, exact[0]),
+        to: lineAt(content, exact[exact.length - 1] + old_text.length - 1),
+        tier: 'exact',
+        count: exact.length,
+      },
+    };
+  }
+
+  const lines = content.split('\n');
+  const oldLines = stripNewline(old_text).split('\n');
+  const newLines = new_text === '' ? [] : stripNewline(new_text).split('\n');
+  const tiers: [Tier, (s: string) => string][] = [
+    ['trailing-space', (s) => s.trimEnd()],
+    ['indentation', (s) => s.trim()],
+  ];
+  for (const [tier, norm] of tiers) {
+    const want = oldLines.map(norm);
+    const hits: number[] = [];
+    for (let i = 0; i + want.length <= lines.length; i++) {
+      if (want.every((w, j) => norm(lines[i + j]) === w)) hits.push(i);
+    }
+    if (hits.length === 0) continue;
+    if (hits.length > 1) {
+      return { error: `old_text matches ${hits.length} places (lines ${hits.map((i) => i + 1).join(', ')}); add context to make it unique` };
+    }
+    const i = hits[0];
+    const out = tier === 'trailing-space' ? newLines : reindent(newLines, oldLines, lines.slice(i, i + oldLines.length));
+    return {
+      content: [...lines.slice(0, i), ...out, ...lines.slice(i + oldLines.length)].join('\n'),
+      applied: { from: i + 1, to: i + oldLines.length, tier, count: 1 },
+    };
+  }
+
+  const target = oldLines.find((l) => l.trim() !== '')?.trim();
+  const first = target ? lines.flatMap((l, i) => (l.includes(target) ? [i + 1] : [])) : [];
+  if (first.length > 0) return { error: `old_text not found; first line appears at line ${first.slice(0, 5).join(', ')}` };
+  return { error: 'old_text not found' };
+}
+
+const stripNewline = (s: string) => (s.endsWith('\n') ? s.slice(0, -1) : s);
+const lineAt = (content: string, index: number) => content.slice(0, index).split('\n').length;
+const indentOf = (line: string) => line.match(/^\s*/)![0];
+
+// Swaps the indentation of old_text's first non-blank line for that of the matched window's first non-blank line.
+function reindent(newLines: string[], oldLines: string[], windowLines: string[]): string[] {
+  const firstNonBlank = (ls: string[]) => ls.find((l) => l.trim() !== '') ?? '';
+  const oldIndent = indentOf(firstNonBlank(oldLines));
+  const windowIndent = indentOf(firstNonBlank(windowLines));
+  return newLines.map((l) => {
+    if (l.trim() === '') return '';
+    return windowIndent + (l.startsWith(oldIndent) ? l.slice(oldIndent.length) : l.trimStart());
+  });
 }

