+import { expect, test } from "bun:test";
+import { distinctInWindow, type Event } from "./window";
+
+// The original O(n^2) implementation, kept as the reference.
+function reference(events: Event[], windowMs: number): number[] {
+  return events.map((e) => {
+    const keys = new Set<string>();
+    for (const other of events) if (other.t > e.t - windowMs && other.t <= e.t) keys.add(other.key);
+    return keys.size;
+  });
+}
+
+// Small deterministic PRNG (mulberry32) so failures reproduce.
+function rng(seed: number): () => number {
+  return () => {
+    seed |= 0;
+    seed = (seed + 0x6d2b79f5) | 0;
+    let x = Math.imul(seed ^ (seed >>> 15), 1 | seed);
+    x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x;
+    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
+  };
+}
+
+const TIMES = [0, -0, 0.1, 0.2, 0.3, 0.1 + 0.2, 1e300, -1e300, Number.MAX_VALUE, -Number.MAX_VALUE, 5e-324, 1, 2, 3, 5, 10];
+const KEYS = ["a", "b", "1"];
+const WINDOWS = [0.1, 1, 5e-324, 1e300, 5, 10];
+
+test("matches the original implementation on random inputs", () => {
+  const next = rng(42);
+  const pick = <T>(xs: T[]): T => xs[Math.floor(next() * xs.length)];
+  for (let trial = 0; trial < 3000; trial++) {
+    const n = Math.floor(next() * 13);
+    const events = Array.from({ length: n }, () => ({ t: pick(TIMES), key: pick(KEYS) }));
+    const windowMs = pick(WINDOWS);
+    expect(distinctInWindow(events, windowMs)).toEqual(reference(events, windowMs));
+  }
+});
+
+test("matches the original implementation on larger inputs with many equal times", () => {
+  const next = rng(7);
+  for (let trial = 0; trial < 20; trial++) {
+    const events = Array.from({ length: 300 }, () => ({ t: Math.floor(next() * 20), key: `k${Math.floor(next() * 40)}` }));
+    const windowMs = 1 + Math.floor(next() * 10);
+    expect(distinctInWindow(events, windowMs)).toEqual(reference(events, windowMs));
+  }
+});
+
+test("-0 and 0 are the same time", () => {
+  const events = [
+    { t: -0, key: "a" },
+    { t: 0, key: "b" },
+  ];
+  expect(distinctInWindow(events, 1)).toEqual([2, 2]);
+  expect(reference(events, 1)).toEqual([2, 2]);
+});
