@@ -0,0 +1,33 @@
+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+import { region } from '../src/pricing/regions.ts';
+import { bulkDiscount } from '../src/pricing/discounts/bulk.ts';
+
+describe('pricing rules', () => {
+  test('UK free shipping threshold is 4000', () => {
+    expect(region('UK').freeShippingFrom).toBe(4000);
+  });
+
+  test('bulk tiers start at 10 and 50 units', () => {
+    expect(bulkDiscount(9, 10000)).toBe(0);
+    expect(bulkDiscount(10, 10000)).toBe(500);
+    expect(bulkDiscount(49, 10000)).toBe(500);
+    expect(bulkDiscount(50, 10000)).toBe(1000);
+  });
+
+  test('lines of the same sku count toward the bulk tier together', () => {
+    // 12 mugs = 5400; 5% bulk = 270
+    const t = totals(cart('US', [['MUG', 6], ['MUG', 6]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.lines[0].discount).toBe(270);
+  });
+
+  test('shipping is judged on the discounted subtotal after the coupon', () => {
+    // 2 bags + 2 mugs = 5300 (free before coupon); SAVE10 takes 530 -> 4770, under 5000
+    // shipping 800; tax 7% of 5570 = 389.9 -> 390; total 4770 + 800 + 390
+    expect(totals(cart('US', [['BAG', 2], ['MUG', 2]], 'SAVE10'))).toMatchObject({
+      subtotal: 5300, coupon: 530, shipping: 800, tax: 390, total: 5960,
+    });
+  });
+});

